import{_ as n}from"./chunks/start.DZ5W2yLf.js";import{_ as i,C as a,o as r,c as l,a3 as d,j as e,E as o}from"./chunks/framework.B9qR_F1m.js";const x=JSON.parse('{"title":"Your first mission in 5 minutes","description":"","frontmatter":{},"headers":[],"relativePath":"en/start/first-mission.md","filePath":"en/start/first-mission.md"}'),p={name:"en/start/first-mission.md"},h={class:"tiles"},g={class:"tile",href:"../dtc"},c={class:"tile-icon"},m={class:"tile",href:"../../ablaeufe/designer"},u={class:"tile-icon"},k={class:"tile",href:"../../gemeinsam/teilen"},f={class:"tile-icon"};function b(w,t,y,_,S,C){const s=a("Icon");return r(),l("div",null,[t[6]||(t[6]=d('<h1 id="your-first-mission-in-5-minutes" tabindex="-1">Your first mission in 5 minutes <a class="header-anchor" href="#your-first-mission-in-5-minutes" aria-label="Permalink to &quot;Your first mission in 5 minutes&quot;">​</a></h1><p>Goal: open a mission, build a cartridge and a lineup card for an F-16 flight, and write it all back into the .miz. In DCS, the jet then loads your steerpoints and the kneeboard holds your pages.</p><p><img src="'+n+'" alt="Shardwing&#39;s start screen" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">Just want to look around?</p><p>On the start screen, <strong>Beispiel ansehen</strong> (view example) opens the demo mission &quot;Operation Desert Veil&quot;: two F-16 flights over Syria, fully planned with cartridges, lineup cards, kneeboards, timing and IADS. You can change and save it like any other mission.</p></div><ol class="steps"><li><p><strong>Open the mission.</strong> Drag your <code>.miz</code> into the window – or click <strong>Öffnen</strong> (open) at the top left (<kbd>⌘O</kbd> / <kbd>Ctrl+O</kbd>). Shardwing reads the mission in a second or two and jumps to the <strong>Flights</strong> area.</p></li><li><p><strong>Pick a flight.</strong> On the left are all playable flights, sorted by coalition. Click an F-16 flight. The map shows its route, the table below lists all its waypoints.</p></li><li><p><strong>Release threats.</strong> Switch to <strong>Intel</strong>. All SAM sites of the mission start out <em>hidden</em> – Shardwing tells pilots nothing they aren&#39;t supposed to know. Click a site and release it, or use <strong>Alle aus Mission freigeben</strong> (release all from mission).</p></li><li><p><strong>Create a cartridge.</strong> Back to <strong>Flights</strong>, tab <strong>DTC</strong>, then <strong>Neu aus Route</strong> (new from route). Shardwing takes over the waypoints, radios and the released threats. Your own CMDS programs stay untouched. (<a href="./../dtc">More on the DTC</a>)</p></li><li><p><strong>Fill in the lineup card.</strong> Tab <strong>Lineup Card</strong>: enter joker and bingo, done. On the right you see the pages as they will look on the kneeboard – lineup card, comm card, route map. <strong>In .miz einbetten …</strong> (embed in .miz) puts them on the kneeboard of the aircraft type. To get the pages in English, go to <strong>Kneeboards</strong> and set <strong>Sprache der Seiten</strong> (language of the pages) to <em>English</em>.</p></li><li><p><strong>Save.</strong> Click <strong>Speichern</strong> (save) at the top (<kbd>⌘S</kbd> / <kbd>Ctrl+S</kbd>). The desktop app writes the .miz back to its place and keeps a backup of the old version; in the browser you get it as a download.</p></li><li><p><strong>Fly it in DCS.</strong> Open the mission in the Mission Editor or start it directly. In the cockpit, load the cartridge on the DTE page (or tick <strong>AutoLoad</strong> beforehand) – the steerpoints are in the DED, and the kneeboard (key <kbd>K</kbd>) shows your pages.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">Nothing gets broken</p><p>Shardwing only changes what you edit. Everything it doesn&#39;t know – triggers, scripts, units, weather, mod data – stays exactly as the Mission Editor wrote it. And <kbd>⌘Z</kbd> / <kbd>Ctrl+Z</kbd> undoes every step.</p></div><h2 id="where-next" tabindex="-1">Where next? <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next?&quot;">​</a></h2>',7)),e("div",h,[e("a",g,[e("span",c,[o(s,{name:"compass"})]),t[0]||(t[0]=e("span",{class:"tile-title"},"DTC – Cartridges",-1)),t[1]||(t[1]=e("span",{class:"tile-text"},"Steerpoints, radios, threats and CMDS for F-16C and F/A-18C.",-1))]),e("a",m,[e("span",u,[o(s,{name:"pencil-ruler"})]),t[2]||(t[2]=e("span",{class:"tile-title"},"Designer workflow (German)",-1)),t[3]||(t[3]=e("span",{class:"tile-text"},"From the .miz to the finished briefing package.",-1))]),e("a",k,[e("span",f,[o(s,{name:"users"})]),t[4]||(t[4]=e("span",{class:"tile-title"},"Planning together (German)",-1)),t[5]||(t[5]=e("span",{class:"tile-text"},"Share the mission, pilots sign up themselves.",-1))])])])}const T=i(p,[["render",b]]);export{x as __pageData,T as default};
